/* ================= セーブ ================= */
const KEY = "projectStage_v1";
const DEF_META = { dp: 0, plays: 0, hall: [], skills: [], best: {}, outfits: [], up: { st: 0, stam: 0, eff: 0, fan: 0, aff: 0 }, mute: false, evseen: [] };
let DB = { meta: { ...DEF_META }, run: null };
try {
  const raw = JSON.parse(localStorage.getItem(KEY) || "{}");
  DB.meta = Object.assign({}, DEF_META, raw.meta || {});
  DB.meta.up = Object.assign({}, DEF_META.up, DB.meta.up || {});
  DB.run = raw.run || null;
} catch (e) { }
const save = () => { try { localStorage.setItem(KEY, JSON.stringify(DB)); } catch (e) { } };
let G = null;

/* ================= 音 ================= */
let AC = null;
function beep(f, dur, type = "sine", vol = .13, when = 0) {
  if (DB.meta.mute) return;
  try {
    AC = AC || new (window.AudioContext || window.webkitAudioContext)();
    const o = AC.createOscillator(), g = AC.createGain();
    o.type = type; o.frequency.value = f;
    g.gain.setValueAtTime(vol, AC.currentTime + when);
    g.gain.exponentialRampToValueAtTime(.001, AC.currentTime + when + dur);
    o.connect(g); g.connect(AC.destination);
    o.start(AC.currentTime + when); o.stop(AC.currentTime + when + dur + .05);
  } catch (e) { }
}
const sfx = {
  tap: () => beep(440, .04, "square", .04),
  good: () => { beep(660, .08); beep(880, .11, "sine", .12, .06); },
  great: () => { beep(660, .06); beep(990, .06, "sine", .13, .05); beep(1320, .16, "sine", .14, .11); },
  bad: () => beep(120, .3, "sawtooth", .1),
  clear: () => [523, 659, 784, 1046].forEach((f, i) => beep(f, .22, "sine", .13, i * .12)),
  drum: () => { for (let i = 0; i < 3; i++) beep(90, .16, "triangle", .12, i * .22); },
  skill: () => [523, 784, 1046, 1568].forEach((f, i) => beep(f, .18, "triangle", .13, i * .09)),
  shop: () => { beep(880, .07, "triangle"); beep(1174, .11, "triangle", .12, .06); },
};

/* ================= 小道具 ================= */
function toast(msg) {
  const t = document.createElement("div"); t.className = "tst"; t.innerHTML = msg;
  $("toast").appendChild(t);
  setTimeout(() => { t.style.transition = "opacity .4s"; t.style.opacity = 0; setTimeout(() => t.remove(), 400); }, 2000);
}
const CONFETTI_COLORS = ["#5ac8fa", "#a06bf0", "#8ce65a", "#ffd60a", "#ff8ad8", "#ff5e5e", "#4ad6b8", "#f5f5f7"];
function confetti(n = 40) {
  for (let i = 0; i < n; i++) {
    const c = document.createElement("div"); c.className = "conf2";
    c.style.background = pick(CONFETTI_COLORS);
    c.style.left = Math.random() * 100 + "vw";
    c.style.width = (5 + Math.random() * 6) + "px";
    c.style.height = (9 + Math.random() * 9) + "px";
    c.style.setProperty("--rz", (Math.random() * 900 - 450) + "deg");
    c.style.animationDuration = (1.8 + Math.random() * 2) + "s";
    c.style.animationDelay = (Math.random() * .6) + "s";
    document.body.appendChild(c); setTimeout(() => c.remove(), 4600);
  }
}
function show(id) {
  document.querySelectorAll(".scr").forEach(s => s.classList.remove("on"));
  $(id).classList.add("on");
}
function openSheet(html) { $("sheetPanel").innerHTML = html; $("ovSheet").classList.add("on"); }
function closeSheet() { $("ovSheet").classList.remove("on"); }
const esc = s => String(s).replace(/[<>&]/g, c => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;" }[c]));
const nm = () => G ? G.name : "きみ";
const rep = t => t.replace(/\{name\}/g, esc(nm()));
const PERSON = id => CANDS[id] || COACHES[id] || JUDGES.find(j => j.id === id);
const pImg = (id, w, h) => `<img src="${PERSON(id).img}" alt="${PERSON(id).n}" style="width:${w}px;height:${h || w}px;border-radius:4px;object-fit:cover;display:block">`;

/* ================= タイトル ================= */
function renderTitle() {
  $("tDp").textContent = DB.meta.dp;
  $("tPlays").textContent = DB.meta.plays;
  $("btnCont").disabled = !DB.run;
  $("muteBtn").textContent = DB.meta.mute ? "🔇" : "🔊";
  show("scrTitle");
}
$("muteBtn").onclick = () => { DB.meta.mute = !DB.meta.mute; save(); $("muteBtn").textContent = DB.meta.mute ? "🔇" : "🔊"; };
$("btnNew").onclick = () => { sfx.tap(); if (DB.run && !confirm("いまの挑戦データは消えます。よろしいですか？")) return; renderCreate(); };
$("btnCont").onclick = () => {
  sfx.tap(); G = DB.run;
  /* 旧バージョンのセーブとの互換 */
  G.fixedSeen = G.fixedSeen || []; G.evseen = G.evseen || [];
  G.song = G.song || null; G.solo = G.solo || null; G.leader = G.leader || null;
  G.revengeOK = G.revengeOK || 0; G.milesSeen = G.milesSeen || []; G.fanMilesSeen = G.fanMilesSeen || [];
  if (!("takuto" in G.aff)) {
    G.aff.takuto = 0; G.aff.hara = 0;
    if (G.auds.length < 2 && !G.alive.includes("hara")) G.alive.push("hara");
    if (G.auds.length < 3 && !G.alive.includes("takuto")) G.alive.push("takuto");
  }
  if (!("shino" in G.aff)) {
    ["noa", "roi", "masaki", "shuto", "shino"].forEach(id => { G.aff[id] = 0; });
    if (G.auds.length < 1) G.alive.push("noa");
    if (G.auds.length < 2) G.alive.push("roi");
    if (G.auds.length < 3) G.alive.push("masaki");
    if (G.auds.length < 4) G.alive.push("shuto");
    G.alive.push("shino");
  }
  G.sushiDone = G.sushiDone || false; G.saisonDone = G.saisonDone || false; G.recentScores = G.recentScores || [];
  G.talent = G.talent || {}; G.usedExits = G.usedExits || [];
  G.hinoUsed = G.hinoUsed || {}; G.hinoSceneUsed = G.hinoSceneUsed || [];
  G.nichiUsed = G.nichiUsed || []; G.nichiSceneUsed = G.nichiSceneUsed || []; G.sapixSceneUsed = G.sapixSceneUsed || []; G.visitCount = G.visitCount || 0;
  G.liveDone = G.liveDone || false; G.concertDone = G.concertDone || false; G.qboxUsed = G.qboxUsed || [];
  renderMain();
};
