function hinoPickTalk(member) {
  G.hinoUsed = G.hinoUsed || {};
  const used = G.hinoUsed[member] || [];
  const all = HINO_TALKS[member];
  let avail = all.map((_, i) => i).filter(i => !used.includes(i));
  if (!avail.length) { G.hinoUsed[member] = []; avail = all.map((_, i) => i); }
  const i = avail[Math.floor(Math.random() * avail.length)];
  G.hinoUsed[member] = (G.hinoUsed[member] || []).concat(i);
  return all[i];
}
function startHino(done) {
  G.hinoLast = G.day;
  const members = Object.keys(HINO_TALKS).filter(id => G.alive.includes(id));
  /* シノ優先＋もう1人ランダム */
  const first = members.includes("shino") ? "shino" : (members[0] || "shino");
  const others = members.filter(m => m !== first);
  const second = others.length ? others[Math.floor(Math.random() * others.length)] : null;
  G.hinoSceneUsed = G.hinoSceneUsed || [];
  let sAvail = HINO_SCENES.map((_, i) => i).filter(i => !G.hinoSceneUsed.includes(i));
  if (!sAvail.length) { G.hinoSceneUsed = []; sAvail = HINO_SCENES.map((_, i) => i); }
  const sIdx = sAvail[Math.floor(Math.random() * sAvail.length)];
  G.hinoSceneUsed.push(sIdx);
  const qs = [...HINO_QS].sort(() => Math.random() - .5).slice(0, 3);

  const doQuiz = () => startQuiz({
    mode: "lesson", genre: "kufuu", lv: 3, total: 3,
    fixed: qs.map(q => ({ ...q, small: true, time: 75, genre: "kufuu" })),
    title: "🏫 学校算数チャレンジ",
    onEnd: r => {
      G.totalQ += r.total; G.totalOK += r.correct;
      const heal = 30;
      G.stam = Math.min(G.maxStam, G.stam + heal);
      addStat("me", 6);
      G.cond = clamp(G.cond + 1, 0, 4);
      const perfect = r.correct === 3;
      G.fans += perfect ? 1500 : 800;
      confetti(perfect ? 50 : 25); sfx.clear(); save();
      $("resPanel").innerHTML = `
        <div class="resHead">
          <div class="lbl">🏫 学校算数チャレンジ</div>
          <div class="resScore" style="font-size:34px">${r.correct} / 3 問</div>
          <div class="resRank" style="background:${perfect ? "#ffcf5c" : "#4ad6b8"};color:#0a0a11">${perfect ? "🌸 生徒たち大かんせい！" : "たのしかった！"}</div>
        </div>
        <div class="gains">
          <div class="gain"><span>📈 注目度（学校訪問がニュースに）</span><b>+${perfect ? 1500 : 800}</b></div>
          <div class="gain"><span>精神力（子どもたちの応援）</span><b>+6</b></div>
          <div class="gain"><span>体力（心があたたまった）</span><b>+${heal}</b></div>
          <div class="gain"><span>調子</span><b>アップ</b></div>
        </div>
        <button class="btn" id="resOk">▶</button>`;
      $("ovResult").classList.add("on");
      $("resOk").onclick = () => {
        sfx.tap(); $("ovResult").classList.remove("on");
        showEvent({
          c: first,
          t: perfect
            ? "あかり「全問正解！？ すごい！！ わたしのお兄ちゃんたち、天才！！」\n\n（生徒たちが取り囲んで、大さわぎになった）\n\nあかり「わたしも……わたしも、頑張る！ 受験、ぜったい受かる！\nだから、ぜったいデビューしてね！ 約束だよ！！」"
            : "あかり「おしかったね！ でも、かっこよかった！\n\nわたしも、まちがえても頑張る。\nお兄ちゃんたちみたいに、あきらめないもん。\n\n……また来てね！ 約束だよ！」",
          ch: [{ t: "「約束！」", fx: {}, after: done }]
        });
      };
    }
  });

  showEvent({
    c: "kanade",
    t: "「今日はレッスンお休み。……そのかわり、特別な仕事だよ。\n\n品川区の日野学園。日本で最初の小中一貫校のモデルになった学校。\nそこの小学生と、ふれあいイベントなんだ。\n\n子どもたちの前に立つのも、アイドルの大事な仕事。\n……行こうか」",
    ch: [{ t: "🏫 日野学園へ！", fx: {}, after: () => showEvent({
      c: first,
      t: hinoPickTalk(first),
      ch: [{ t: "▶", fx: { st: { me: 3 } }, after: () => {
        const goScene = () => showEvent({
          c: second || first,
          t: HINO_SCENES[sIdx],
          ch: [{ t: "▶", fx: { stam: 10 }, after: () => showEvent({
            c: first,
            t: "先生「せっかくなので、みなさん。\n算数の授業に、とび入り参加してみませんか？\n\n生徒たちと勝負です。……本気で来てくださいね？」\n\nあかり「がんばれー！ お兄ちゃんたちー！」",
            ch: [{ t: "🔥 受けて立つ！", fx: {}, after: doQuiz }]
          }) }]
        });
        if (second) showEvent({
          c: second,
          t: hinoPickTalk(second),
          ch: [{ t: "▶", fx: { st: { me: 2 }, aff: { [second]: 5 }, silent: true, msg: "あたたかい時間だった" }, after: goScene }]
        });
        else goScene();
      } }]
    }) }]
  });
}

/* ================= 受験生応援キャンペーン：日能研 目黒校 ================= */
/* タイムレッスーには「受験生を応援したい」という思いがある */
const NICHI_AKARI = [
  "シノ「あれ？ ……あかりちゃん！？\nこないだ学校でも会ったよね？ ここの塾に通っているんだ！\n\nあかり「シノお兄ちゃん！！ なんで塾にいるの！？」\n\nシノ「……受験生応援キャンペーン。タイムレッスーの先輩たちの発案でね。\n……まさか、また会えるとは。ぼくたち、縁があるね」",
  "あかり「見て、今日のテスト、96点だった！」\n\nシノ「96点！？ すごい……！\n\n……ちなみに、まちがえた4点分は、どこ？\n\n……そう、それを今から一緒に見るのが、96点を100点にする勉強。\n点数は『結果』で、まちがい直しは『未来』なんだ」",
  "あかり「クラスが下がっちゃった……」\n\nシノ「……そっか。くやしいね。\n\nでもね、クラスはエレベーターみたいなもの。\n下がった階で何を積むかで、次に上がる高さが決まる。\n\nぼくもオーディションで順位が下がったこと、あるよ。\n……そのあとが、いちばん伸びた」",
  "（自習室で、あかりが塾弁を食べていた）\n\nあかり「ママのお弁当。……ちょっと冷めてるけど、おいしいの」\n\nシノ「……いいお弁当だね。\n\n夜まで勉強する日のお弁当って、応援の手紙みたいなものだから。\n……ちゃんと味わって食べる子は、強いよ」",
  "あかり「ねえシノお兄ちゃん、志望校ってどうやって決めたの？」\n\nシノ「……文化祭に行って、『ここに通ってる自分』を想像できたかどうか。\n\n偏差値は道具で、目的地じゃない。\nあかりちゃんが『ここで青春したい』って思える学校が、正解の学校。\n\n……もう、あるんでしょ？ その顔は、ある顔だ」",
  "（演習の時間。あかりが鉛筆を止めて、ぼーっとしていた）\n\nシノ「……眠い？\n\n……わかる。塾の夕方って、魔の時間なんだよね。\nそういうときはね、『1問だけ全力』って決めるの。\n\n1問に全力を出すと、脳が再起動する。\n……ほら、目が覚めてきた」",
  "あかり「この子、ゆりあちゃん。仲良しなの」\n\nゆりあ「……ほんものだ。……あかりの言ってたお兄ちゃんだ」\n\nシノ「……ぼくのこと、話してくれてたんだ。\n\nあかりちゃん、友だちと一緒に通えるのは、宝物だよ。\n受験は個人戦に見えて、ほんとはチーム戦だから」",
  "（帰り際、あかりが問題集を見せてきた）\n\nあかり「ここ、どうしてもわかんないの」\n\nシノ「……どれ。……ああ、これはね、図を描くと一瞬だよ。\n\n（さらさらと線分図を描く）\n\n……ね？ 解けない問題の9割は、『図にしてない』だけ。\n手を動かせば、頭はあとからついてくる」",
];
const NICHI_SCENES = [
  "（日能研目黒校の教室。生徒たちがざわついた）\n\nあかり「あっ！！」　ゆりあ「え、うそ、ほんもの？」\nもか「学校に来た人たちだ！」　いっちゃん「サインもらっていい！？」\nまき「テストの日なのに、テンション上がっちゃう……！」\n\n先生「はいはい、静かに！ ……私もあとでサインください」",
  "（いっちゃんが、候補生たちに塾の説明をしてくれた）\n\nいっちゃん「ここはね、テストの成績で席が決まるんだよ。\n\nぼく、先週まで一番後ろだったけど、今週は真ん中！」\n\nハラ（いたら）もメンバーも、感心してうなずいた。\n『順位が出る世界』を生きてるのは、おたがいさまだった。",
  "（まきが、暗記カードの束を見せてくれた）\n\nまき「都道府県、ぜんぶ言えるよ。県庁所在地も」\n\n（本当に全部言えた。拍手が起きた）\n\nまき「……毎日、お風呂で3個ずつ覚えたの」\n\n毎日3個。その積み重ねの重さを、候補生たちは知っていた。",
  "（もかが、こっそり打ち明けてくれた）\n\nもか「ほんとはね、塾、やめたいって思う日もあるの。\n\n……でも、あかりちゃんが『いっしょに受かろう』って言ってくれたから。\nだから来てる。……友だちってすごいね」\n\n（それを聞いていたあかりが、照れて逃げた）",
  "（ゆりあが、時間割を見せてくれた）\n\nゆりあ「月・水・金が塾で、火曜がピアノ。土曜はテスト。\n\n……いそがしい？ うーん、いそがしい。\nでも、ひまより、いそがしいほうが、なんか、好き」\n\n（メンバー全員が、深くうなずいた。……わかる、と）",
  "（帰りのエレベーター前。生徒たちが並んで手を振った）\n\nあかり「らいしゅうのテスト、がんばるね！」\nいっちゃん「ぼくも席、前にする！」\nまき「デビューしたら、ぜったい観に行く！」\n\n目黒の夜の街に、小さな声援がひびいた。\n……負けていられない、と全員が思った。",
];
const NICHI_QS = [
  { q: "塾のテストは150点満点。あかりは96点。満点まであと何点？", a: { t: "num", v: 54, unit: "点" }, tag: "塾算" },
  { q: "目黒校は4クラス、1クラス24人。ぜんぶで何人？", a: { t: "num", v: 96, unit: "人" }, tag: "塾算" },
  { q: "宿題は計算を毎日20問。1週間（7日）では何問？", a: { t: "num", v: 140, unit: "問" }, tag: "塾算" },
  { q: "授業は70分×3コマ。ぜんぶで何分？", a: { t: "num", v: 210, unit: "分" }, tag: "塾算" },
  { q: "テキストは上巻168ページ、下巻168ページ。合わせて何ページ？", a: { t: "num", v: 336, unit: "ページ" }, tag: "塾算" },
  { q: "クラス100人のうち85人が宿題を出した。提出したのは全体の何%？", a: { t: "num", v: 85, unit: "%" }, tag: "塾算（割合）" },
  { q: "あかりとゆりあのテストは合わせて180点。あかりが12点高い。あかりは何点？", a: { t: "num", v: 96, unit: "点" }, tag: "塾算（和差算）", note: "(180＋12)÷2" },
  { q: "1問5点の問題と1問10点の問題が合わせて14問で100点満点。5点の問題は何問？", a: { t: "num", v: 8, unit: "問" }, tag: "塾算（つるかめ算）", note: "10×14－100＝40、40÷(10－5)" },
  { q: "家から塾まで25分かかる。授業の10分前に着くには、授業の何分前に家を出る？", a: { t: "num", v: 35, unit: "分前" }, tag: "塾算" },
  { q: "模試の算数は62点、国語は54点。差は何点？", a: { t: "num", v: 8, unit: "点" }, tag: "塾算" },
];
function startNichinoken(done) {
  G.nichiLast = G.day;
  G.nichiUsed = G.nichiUsed || []; G.nichiSceneUsed = G.nichiSceneUsed || [];
  const hasShino = G.alive.includes("shino");
  let tIdx = -1;
  if (hasShino) {
    let avail = NICHI_AKARI.map((_, i) => i).filter(i => !G.nichiUsed.includes(i));
    if (!avail.length) { G.nichiUsed = []; avail = NICHI_AKARI.map((_, i) => i); }
    tIdx = avail[Math.floor(Math.random() * avail.length)];
    G.nichiUsed.push(tIdx);
  }
  let sAvail = NICHI_SCENES.map((_, i) => i).filter(i => !G.nichiSceneUsed.includes(i));
  if (!sAvail.length) { G.nichiSceneUsed = []; sAvail = NICHI_SCENES.map((_, i) => i); }
  const sIdx = sAvail[Math.floor(Math.random() * sAvail.length)];
  G.nichiSceneUsed.push(sIdx);
  const qs = [...NICHI_QS].sort(() => Math.random() - .5).slice(0, 3);
  const spk = hasShino ? "shino" : (["takuto", "masaki", "daigo", "hara", "shuto"].find(id => G.alive.includes(id)) || "kanade");

  const doQuiz = () => startQuiz({
    mode: "lesson", genre: "kufuu", lv: 3, total: 3,
    fixed: qs.map(q => ({ ...q, small: true, time: 75, genre: "kufuu" })),
    title: "📚 日能研チャレンジ",
    onEnd: r => {
      G.totalQ += r.total; G.totalOK += r.correct;
      G.stam = Math.min(G.maxStam, G.stam + 25);
      addStat("me", 6);
      G.cond = clamp(G.cond + 1, 0, 4);
      const perfect = r.correct === 3;
      G.fans += perfect ? 1500 : 800;
      confetti(perfect ? 50 : 25); sfx.clear(); save();
      $("resPanel").innerHTML = `
        <div class="resHead">
          <div class="lbl">📚 日能研チャレンジ</div>
          <div class="resScore" style="font-size:34px">${r.correct} / 3 問</div>
          <div class="resRank" style="background:${perfect ? "#ffcf5c" : "#4ad6b8"};color:#0a0a11">${perfect ? "🌸 塾生も先生も大かんせい！" : "受験生応援、大成功！"}</div>
        </div>
        <div class="gains">
          <div class="gain"><span>📈 注目度（応援キャンペーンが話題に）</span><b>+${perfect ? 1500 : 800}</b></div>
          <div class="gain"><span>精神力（受験生の本気にふれた)</span><b>+6</b></div>
          <div class="gain"><span>体力</span><b>+25</b></div>
          <div class="gain"><span>調子</span><b>アップ</b></div>
        </div>
        <button class="btn" id="resOk">▶</button>`;
      $("ovResult").classList.add("on");
      $("resOk").onclick = () => {
        sfx.tap(); $("ovResult").classList.remove("on");
        showEvent({
          c: spk,
          t: "あかり「今日、来てくれてありがとう！\nテストの前だったから、元気もらっちゃった。\n\nわたしたちも頑張るから、お兄ちゃんたちも頑張ってね！\n……次は、テレビで会おうね！」",
          ch: [{ t: "「テレビで会おう！」", fx: {}, after: done }]
        });
      };
    }
  });

  showEvent({
    c: "tsukasa",
    t: "フマ「今日は特別な仕事だ。\n\n……おれたちタイムレッスーには、ひとつの思いがある。\n『受験生を応援したい』。夢に向かって机に向かうやつは、おれたちの同志だ。\n\n受験生応援キャンペーン。今日は日能研の目黒校に、サプライズ訪問する。\n……子どもたちの本気、見てこい」",
    ch: [{ t: "📚 目黒校へ！", fx: {}, after: () => {
      const goScene = () => showEvent({
        c: spk,
        t: NICHI_SCENES[sIdx],
        ch: [{ t: "▶", fx: { stam: 8 }, after: () => showEvent({
          c: spk,
          t: "先生「せっかくですから、みなさんも演習に参加しませんか？\n\n今日の単元、なかなか手ごわいですよ。\n……塾生のみんな、お兄さんたちの実力、見てみたいよね？」\n\n生徒たち「「見たーい！！」」",
          ch: [{ t: "🔥 やります！", fx: {}, after: doQuiz }]
        }) }]
      });
      if (tIdx >= 0) showEvent({
        c: "shino",
        t: NICHI_AKARI[tIdx],
        ch: [{ t: "▶", fx: { st: { me: 3 }, aff: { shino: 4 }, silent: true, msg: "シノとあかりの時間" }, after: goScene }]
      });
      else goScene();
    } }]
  });
}

/* ================= 受験生応援キャンペーン：SAPIX 白金校 ================= */
const SAPIX_SCENES = [
  "（SAPIX白金校。教室の空気が、ピリッとしていた）\n\nりょうたろう「あ、学校に来た人たちだ」\nりょうたろう「ぼく、開成志望です」\nじゅんた「ぼくは麻布。きみたちのオーディションの倍率は？」\nかずや「2万分の5……約4000倍か。開成より高いね」\n\nもとき「……計算はやっ」\nさとゆき「SAPIXだからね」",
  "（りょうたろうが、志望校について語ってくれた）\n\nりょうたろう「開成を受ける理由？ 『一番だから』じゃないよ。\n文化祭に行ったら、先輩たちが、こう、自由で。\n\n『ここで6年過ごしたい』って思ったんだ」\n\n（志望理由がしっかりしている。候補生たちは静かに感動した）",
  "（かずやが、ノートを見せてくれた）\n\nかずや「まちがえた問題は、赤で『なぜまちがえたか』を書くんだ。\n『計算ミス』じゃなくて『くり上がりを暗算でやったから』って。\n\n原因を書けば、対策できるでしょ」\n\n（メンバー全員、自分のダンスノートを思い出していた。同じだ、と）",
  "（もときが、休み時間に折り紙を折っていた）\n\nもとき「……緊張したら、手を動かすといいんだ。\n正多面体。……これは正二十面体」\n\nさとゆき「もときは学年で一番、図形につよい」\nもとき「……折ってるからだと思う」\n\n（遊びが力になる。天才の背中を見た気がした）",
  "（さとゆきが、まっすぐ質問してきた）\n\nさとゆき「オーディションと受験、どっちが大変だと思いますか」\n\n……難しい質問だった。考えていると、さとゆきが続けた。\n\n「ぼくは、『比べないで、自分のをやる』が答えだと思ってます」\n\n（小学生に、完敗だった）",
  "（りょうたろうが、そろばんの腕前を見せてくれた）\n\nりょうたろう「フラッシュ暗算、いくよ。……はい、847×36は30492」\n\n（一同、絶句）\n\nりょうたろう「開成の算数は、スピードより『考える力』だけどね。\n速さは、考える時間を作るための道具だよ」",
  "（自習室を見学した。鉛筆の音だけが響いていた）\n\n誰も、しゃべらない。誰も、スマホを見ない。\n小6の背中が、アスリートに見えた。\n\nじゅんた（小声で）「2月1日まで、あと少しだから」\n\n（帰り道、メンバーは誰も口を開かなかった。……やるしかない、と思った）",
  "（りょうたろうと2人になったとき、ぽつりと話してくれた）\n\nりょうたろう「うち、親が厳しくてさ。テストのたびに、よく怒られる。\n\n……大変だよ。正直、大変。\nでもね、あれって期待の裏返しでもあるんだ。\nどうでもよかったら、怒らないでしょ。\n\nだから僕は、頑張るよ」\n\n（その横顔は、小学生じゃなくて、戦う人の顔だった）",
  "（模試の結果が返ってきたらしい。りょうたろうが下を向いていた）\n\nりょうたろう「……成績、悪かった。落ちこんだ。\n\nでもさ、気づいたんだ。\n落ち込んでも、成績は1ミリも良くならないって。\n\nだったら、自分が成長することを信じて、\n1問でも多く問題を解くしかない。……そう思ってる」\n\n（返す言葉が見つからなかった。ただ、全員が自分の練習を思った）",
  "（りょうたろうが、候補生たちに聞いてきた）\n\nりょうたろう「審査に落ちそうになったこと、ある？\n\n……あるんだ。で、どうやって立て直した？」\n\n（真剣な目だった。答えると、小さくうなずいてメモを取った）\n\nりょうたろう「……参考になった。\n受験もオーディションも、立て直した人が勝つんだね」",
  "（帰り際、かずやが言った）\n\nかずや「きみたちの倍率4000倍とぼくらの倍率3倍、\n数字は違うけど、やることは同じだよね。\n\n『今日の自分が、昨日の自分に勝つ』。それだけ」\n\nさとゆき「……かずや、それ、ぼくが言ったやつ」\nかずや「いいものは共有しよう」",
];
const SAPIX_QS = [
  { q: "半径10cmの円の面積は？（円周率3.14）", a: { t: "num", v: 314, unit: "cm²" }, tag: "SAPIX算（円）", note: "10×10×3.14" },
  { q: "3.14×25 は？", a: { t: "num", v: 78.5 }, tag: "SAPIX算（計算）", note: "3.14×25＝314÷4" },
  { q: "4人から2人を選ぶ組み合わせは何通り？", a: { t: "num", v: 6, unit: "通り" }, tag: "SAPIX算（場合の数）" },
  { q: "分速80mで12分歩くと何m進む？", a: { t: "num", v: 960, unit: "m" }, tag: "SAPIX算（速さ）" },
  { q: "8%の食塩水300gにとけている食塩は何g？", a: { t: "num", v: 24, unit: "g" }, tag: "SAPIX算（食塩水）", note: "300×0.08" },
  { q: "5回のテストの平均が92点。最初の4回の平均は90点。5回目は何点？", a: { t: "num", v: 100, unit: "点" }, tag: "SAPIX算（平均）", note: "92×5－90×4" },
  { q: "3、7、11、15、……と増える数の列。10番目の数は？", a: { t: "num", v: 39, unit: "" }, tag: "SAPIX算（数列）", note: "3＋4×9" },
  { q: "ある仕事をAとB2人でやると6日、Aだけだと12日かかる。Bだけだと何日？", a: { t: "num", v: 12, unit: "日" }, tag: "SAPIX算（仕事算）", note: "1/6－1/12＝1/12" },
  { q: "1＋2＋3＋……＋10 は？", a: { t: "num", v: 55, unit: "" }, tag: "SAPIX算（規則性）", note: "(1＋10)×10÷2" },
  { q: "定価1200円の2割引きは何円？", a: { t: "num", v: 960, unit: "円" }, tag: "SAPIX算（割合）", note: "1200×0.8" },
];
function startSapix(done) {
  G.sapixLast = G.day;
  G.sapixSceneUsed = G.sapixSceneUsed || [];
  let avail = SAPIX_SCENES.map((_, i) => i).filter(i => !G.sapixSceneUsed.includes(i));
  if (!avail.length) { G.sapixSceneUsed = []; avail = SAPIX_SCENES.map((_, i) => i); }
  const s1 = avail[Math.floor(Math.random() * avail.length)];
  G.sapixSceneUsed.push(s1);
  let avail2 = SAPIX_SCENES.map((_, i) => i).filter(i => !G.sapixSceneUsed.includes(i));
  if (!avail2.length) avail2 = [s1];
  const s2 = avail2[Math.floor(Math.random() * avail2.length)];
  if (!G.sapixSceneUsed.includes(s2)) G.sapixSceneUsed.push(s2);
  const qs = [...SAPIX_QS].sort(() => Math.random() - .5).slice(0, 3);
  const spk = ["shino", "masaki", "daigo", "takuto", "hara", "shuto"].find(id => G.alive.includes(id)) || "kanade";

  const doQuiz = () => startQuiz({
    mode: "lesson", genre: "kufuu", lv: 4, total: 3,
    fixed: qs.map(q => ({ ...q, small: true, time: 90, genre: "kufuu" })),
    title: "🏆 SAPIXチャレンジ",
    onEnd: r => {
      G.totalQ += r.total; G.totalOK += r.correct;
      G.stam = Math.min(G.maxStam, G.stam + 25);
      addStat("me", 8);
      G.cond = clamp(G.cond + 1, 0, 4);
      const perfect = r.correct === 3;
      G.fans += perfect ? 2000 : 1000;
      confetti(perfect ? 60 : 25); sfx.clear(); save();
      $("resPanel").innerHTML = `
        <div class="resHead">
          <div class="lbl">🏆 SAPIXチャレンジ</div>
          <div class="resScore" style="font-size:34px">${r.correct} / 3 問</div>
          <div class="resRank" style="background:${perfect ? "#ffcf5c" : "#4ad6b8"};color:#0a0a11">${perfect ? "👑 トップ校志望の子たちが拍手！" : "いい勝負だった！"}</div>
        </div>
        <div class="gains">
          <div class="gain"><span>📈 注目度（最難関塾での挑戦が話題に）</span><b>+${perfect ? 2000 : 1000}</b></div>
          <div class="gain"><span>精神力（本物の受験生の集中力を見た)</span><b>+8</b></div>
          <div class="gain"><span>体力</span><b>+25</b></div>
          <div class="gain"><span>調子</span><b>アップ</b></div>
        </div>
        <button class="btn" id="resOk">▶</button>`;
      $("ovResult").classList.add("on");
      $("resOk").onclick = () => {
        sfx.tap(); $("ovResult").classList.remove("on");
        showEvent({
          c: spk,
          t: perfect
            ? "じゅんた「全問正解。……正直、なめてました」\nかずや「訂正します。アイドル、頭いい」\nりょうたろう「合格。ぼくらが認定します」\n\nさとゆき「2月、ぼくらも全問正解してきます。\n……おたがい、選ばれましょう」\n\n（トップ校を狙う男たちとの、固い握手だった）"
            : "かずや「おしかったですね。でも、あきらめない解き方でした」\nじゅんた「うん。過程が良かった。開成でもそこを見ます……たぶん」\n\nさとゆき「2月、ぼくらも本番です。\n……おたがい、選ばれましょう」\n\n（トップ校を狙う男たちとの、固い握手だった）",
          ch: [{ t: "「おたがい、選ばれよう」", fx: { st: { me: 3 } }, after: done }]
        });
      };
    }
  });

  showEvent({
    c: "riku",
    t: "ショリ「受験生応援キャンペーン、第2弾。\n今日はSAPIXの白金校。……最難関中学を目指す子たちの塾だよ。\n\n開成、麻布……日本でいちばん高い山を登ってる小学生たち。\n\n僕たちの世界で言えば、世界大会を目指してる子たち。\n……本物の集中力って、どんなものか。見ておいで」",
    ch: [{ t: "🏆 白金校へ！", fx: {}, after: () => showEvent({
      c: spk,
      t: SAPIX_SCENES[s1],
      ch: [{ t: "▶", fx: { st: { me: 2 } }, after: () => showEvent({
        c: spk,
        t: SAPIX_SCENES[s2],
        ch: [{ t: "▶", fx: { stam: 8 }, after: () => showEvent({
          c: spk,
          t: "先生「では、お客さまにも解いていただきましょう。\n\n今日のデイリーチェックです。\n……SAPIX基準ですので、少々骨がありますよ」\n\nりょうたろう「がんばって！ 解けたら認めてあげる！」",
          ch: [{ t: "🔥 受けて立つ！", fx: {}, after: doQuiz }]
        }) }]
      }) }]
    }) }]
  });
}

/* ================= 企画1：生配信SP ================= */
const LIVE_COMS = {
  good: ["え、この子計算はやすぎw","いまのすごくない！？","天才では","うちの子もこうなってほしい","推せる","手元アップ助かる","ノーミスいけるぞ！","集中力えぐい","この子のファンになりました","かっこいい…","娘が推し始めました","スピードが違う","今日も安定してる","応援せずにいられない","がんばれー！！","この配信毎週見たい","切り抜き確定","正解の瞬間の顔が良い"],
  neutral: ["初見です","タイプロから来ました","この番組おもしろい","何人残ってるんだっけ","BGMいいね","候補生みんな仲良しで好き","シノくん出ないかな","あと何日で審査？","宿題やりながら見てる","おやつ食べながら応援"],
  bad: ["あー惜しい","おっと","緊張してるかな","手が止まった…","がんばれ！","ドンマイ！"],
  comeback: ["立て直した！","メンタル強い","切り替えはやい","そこで戻せるのすごい","これがプロ意識か…"],
};
function startLive(done) {
  showEvent({
    c: "roi",
    t: "ロイ「おい聞いたか！？ 今夜、おれたちの練習が生配信されるって！\n\n全国のファンが、リアルタイムで見てるんだぜ。\nコメントも流れるらしい。……緊張してきた。\n\nでもさ、これってチャンスだよな。\n画面の向こうの誰かを、ファンにできるチャンス」",
    ch: [{ t: "🎥 配信、スタート！", fx: {}, after: () => {
      const L = { viewers: ri(2000, 4000), lastCombo: 0, lastCorrect: 0, trend: false, iv: 0 };
      const layer = $("liveLayer");
      layer.classList.remove("hide");
      $("liveTrend").classList.add("hide");
      $("liveComs").innerHTML = "";
      const spawn = (txt, cls) => {
        const d = document.createElement("div");
        d.className = "liveCom " + (cls || "");
        d.textContent = txt;
        $("liveComs").appendChild(d);
        setTimeout(() => d.remove(), 3800);
      };
      L.iv = setInterval(() => {
        if (!Q) return;
        /* 状態を読んでコメントを流す */
        if (Q.combo > L.lastCombo && Q.combo >= 1) {
          spawn(pick(LIVE_COMS.good), "g");
          L.viewers += ri(60, 160) + Q.combo * ri(30, 80);
        } else if (Q.combo === 0 && L.lastCombo >= 1) {
          spawn(pick(LIVE_COMS.bad), "b");
          L.viewers = Math.max(1500, L.viewers - ri(80, 200));
        } else if (Math.random() < .6) {
          spawn(pick(L.lastCombo === 0 && Q.correct > 0 ? LIVE_COMS.comeback : LIVE_COMS.neutral));
          L.viewers += ri(10, 60);
        }
        L.lastCombo = Q.combo; L.lastCorrect = Q.correct;
        $("liveViewers").textContent = `👁 ${L.viewers.toLocaleString()}人が視聴中`;
        if (!L.trend && (Q.combo >= 5 || L.viewers >= 12000)) {
          L.trend = true;
          $("liveTrend").classList.remove("hide");
          confetti(30);
        }
      }, 850);
      startQuiz({
        mode: "lesson", genre: "kufuu", lv: Math.max(2, lessonLv() - 1), total: 8,
        title: "🎥 生配信スペシャル",
        onEnd: r => {
          clearInterval(L.iv);
          layer.classList.add("hide");
          G.totalQ += r.total; G.totalOK += r.correct;
          const gain = Math.round(L.viewers * (.35 + r.score / 150) * (L.trend ? 1.5 : 1));
          G.fans += gain;
          addStat("ex", 5); addStat("me", 4);
          confetti(L.trend ? 60 : 30); sfx.clear(); save();
          $("resPanel").innerHTML = `
            <div class="resHead">
              <div class="lbl">🎥 生配信スペシャル</div>
              <div class="resScore" style="font-size:34px">${r.correct} / 8 問</div>
              <div class="resRank" style="background:${L.trend ? "#ffcf5c" : "#4ad6b8"};color:#0a0a11">${L.trend ? "🔥 SNSトレンド入り！！" : "配信終了！"}</div>
            </div>
            <div class="gains">
              <div class="gain"><span>👁 最終視聴者数</span><b>${L.viewers.toLocaleString()}人</b></div>
              <div class="gain"><span>📈 注目度（配信を見た人がファンに）</span><b>+${gain.toLocaleString()}</b></div>
              <div class="gain"><span>表現力（カメラの前でも動じない）</span><b>+5</b></div>
              <div class="gain"><span>精神力</span><b>+4</b></div>
            </div>
            <button class="btn" id="resOk">▶</button>`;
          $("ovResult").classList.add("on");
          $("resOk").onclick = () => {
            sfx.tap(); $("ovResult").classList.remove("on");
            showEvent({
              c: "roi",
              t: L.trend
                ? "ロイ「見たかSNS！ おれたち、トレンド入りしてる！！\n\n『#計算はやすぎ候補生』って……なんだこのタグw\n\nでもさ、画面の向こうに、ほんとに人がいたんだな。\n……responsibility、ってやつを感じるぜ。おれたち、もう見られてる側なんだ」"
                : "ロイ「配信、おつかれ！ コメント欄あったかかったな〜。\n\n画面の向こうに、ほんとに応援してる人がいる。\nそれが分かっただけで、明日からの練習、ちょっと変わる気がするよ」",
              ch: [{ t: "▶", fx: { cond: 1 }, after: done }]
            });
          };
        }
      });
    } }]
  });
}

/* ================= 企画2：タイムレッスーのライブにサプライズ出演 ================= */
function startConcert(done) {
  showEvent({
    c: "kanade",
    t: "ソウ「……今夜、僕たちのライブがあるんだ。\n1万人のアリーナ。\n\nそこでね……候補生の紹介コーナーを作った。\nきみたち、ステージに立ちなさい。\n\n……本物の歓声を、浴びておいで」",
    ch: [{ t: "🎤 ……1万人の前に！？", fx: {}, after: () => showEvent({
      c: "tsukasa",
      t: "（本番30分前。楽屋にフマが来た）\n\nフマ「緊張してるか。……いい。それが正常だ。\n\nひとつだけ教えといてやる。\n1万人ってのはな、『1人×1万』だ。\n一番遠い席の1人に届けるつもりでやれ。\n\nそうすりゃ、全員に届く」",
      ch: [{ t: "「1人×1万……」", fx: { st: { me: 4 } }, after: () => showEvent({
        c: "riku",
        t: "（続いて、ショリが顔を出した）\n\nショリ「衣装、似合ってるよ。\n\n……あのさ、僕が初めてアリーナに立った日、\n足が震えて、袖から出られなかったんだ。\n\nそのとき先輩に背中を押されて出たら……世界が変わった。\n\n今日は、僕がきみの背中を押す番。……いっといで」",
        ch: [{ t: "「……はい！」", fx: { st: { ex: 4 } }, after: () => showEvent({
          c: "kanade",
          t: "（ステージ袖。歓声が地鳴りみたいに響いてる）\n\nソウ「……すごい音でしょ。\n\nこの歓声はね、今日はまだ、僕たちのもの。\nでも、いつか、きみのものになる。\n\n……深呼吸して。\n……いってらっしゃい！」",
          ch: [{ t: "🔥 ステージへ！！", fx: { st: { vo: 3 } }, after: () => {
            const genres = ["pi", "frac", "ratio", "gyaku", "kufuu", "bun"];
            const fixed = Array.from({ length: 10 }, (_, i) => {
              const g = MATH.gen(genres[i % genres.length], 5);
              return { ...g, time: Math.round((g.time || 60) * 1.5) };
            });
            startQuiz({
              mode: "lesson", genre: "kufuu", lv: 5, total: 10, fixed,
              title: "🎤 1万人のアリーナ",
              onEnd: r => {
                G.totalQ += r.total; G.totalOK += r.correct;
                const success = r.correct >= r.total - 2;   /* 2ミスまで成功 */
                const gain = success ? ri(9000, 12000) : 1500;
                G.fans += gain;
                if (success) { addStat("ex", 6); addStat("vo", 4); }
                addStat("me", success ? 5 : 8);
                confetti(success ? 80 : 15); if (success) sfx.clear(); save();
                $("resPanel").innerHTML = `
                  <div class="resHead">
                    <div class="lbl">🎤 1万人のアリーナ</div>
                    <div class="resScore" style="font-size:34px">${r.correct} / 10</div>
                    <div class="resRank" style="background:${success ? "#ffcf5c" : "#a5a5bd"};color:#0a0a11">${success ? "🌟 大歓声！！" : "……悔しさを知った夜"}</div>
                  </div>
                  <div class="gains">
                    <div class="gain"><span>📈 注目度</span><b>+${gain.toLocaleString()}</b></div>
                    ${success ? `<div class="gain"><span>表現力（本物のステージ）</span><b>+6</b></div><div class="gain"><span>歌唱力</span><b>+4</b></div><div class="gain"><span>精神力</span><b>+5</b></div>` : `<div class="gain"><span>精神力（悔しさは最強の燃料）</span><b>+8</b></div>`}
                  </div>
                  <button class="btn" id="resOk">▶</button>`;
                $("ovResult").classList.add("on");
                $("resOk").onclick = () => {
                  sfx.tap(); $("ovResult").classList.remove("on");
                  showEvent({
                    c: success ? "tsukasa" : "kanade",
                    t: success
                      ? "（ステージを降りると、客席から名前コールが聞こえた）\n\nフマ「……聞こえるか、あれ。\nおまえの名前だ。もう、おまえのファンだ。\n\n今日の景色、忘れるな。\nあの場所に、自分の力で戻ってこい。\n\n……いいもん見せてもらった。ありがとな」"
                      : "（ステージ袖で、うつむいていた。ソウ先輩がそっと隣に立った）\n\nソウ「……悔しい？\n\n……よかった。悔しいって思えるなら、大丈夫。\n\n僕もね、初ステージはボロボロだったんだ。\nでもその悔しさが、今日までずっと僕を走らせてる。\n\nきみは今夜、一番大事なものを手に入れたんだよ」",
                    ch: [{ t: "▶", fx: { cond: 1 }, after: done }]
                  });
                };
              }
            });
          } }]
        }) }]
      }) }]
    }) }]
  });
}

