const QUICK_QS = [
  { q: "3.14×8 は？", a: { t: "num", v: 25.12 }, tag: "とっさの暗算" },
  { q: "25×16 は？", a: { t: "num", v: 400 }, tag: "とっさの暗算", note: "25×4×4" },
  { q: "99×7 は？", a: { t: "num", v: 693 }, tag: "とっさの暗算", note: "700－7" },
  { q: "12.5×8 は？", a: { t: "num", v: 100 }, tag: "とっさの暗算" },
  { q: "15×15 は？", a: { t: "num", v: 225 }, tag: "とっさの暗算" },
  { q: "1000－374 は？", a: { t: "num", v: 626 }, tag: "とっさの暗算" },
  { q: "36×25 は？", a: { t: "num", v: 900 }, tag: "とっさの暗算", note: "36÷4×100" },
];
function startQBox(done) {
  G.qboxLast = G.day;
  G.qboxUsed = G.qboxUsed || [];
  let avail = QBOX.map((_, i) => i).filter(i => !G.qboxUsed.includes(i));
  if (avail.length < 3) { G.qboxUsed = []; avail = QBOX.map((_, i) => i); }
  const cards = [...avail].sort(() => Math.random() - .5).slice(0, 3);
  cards.forEach(i => G.qboxUsed.push(i));
  let tkGain = 0;
  const askCard = (k, after) => {
    const card = QBOX[cards[k]];
    showEvent({
      c: "tsukasa",
      t: `（フマが質問箱からカードを引いた）\n\nフマ「質問${k + 1}。……${card.q}\n\n30秒でどうぞ。……カメラ回ってるからな」`,
      ch: card.ch.map(c => ({ t: c.t, fx: {}, after: () => {
        if (c.fx && c.fx.st && c.fx.st.tk) tkGain += c.fx.st.tk;
        showEvent({ c: c.rc, t: c.r, ch: [{ t: "▶", fx: c.fx, after }] });
      } }))
    });
  };
  showEvent({
    c: "tsukasa",
    t: "フマ「今日はレッスンじゃない。……バラエティ力審査だ。\n\n歌って踊れるだけのやつは、生き残れない。\nテレビで、ラジオで、しゃべって場を回せるか。\n\n名付けて『ぶっちゃけ質問箱』。\n本音で答えろ。つまんない優等生の答えが、いちばん減点だ」",
    ch: [{ t: "😅 お手やわらかに……", fx: {}, after: () => askCard(0, () => askCard(1, () => {
      /* とっさの暗算タイム */
      const qq = pick(QUICK_QS);
      showEvent({
        c: "riku",
        t: `ショリ「はい、ここで恒例の無茶振りコーナー！\n\n${G.name}くん、とつぜんですが──\n\n**${qq.q}**\n\n……計算キャラなんでしょ？ 見せて見せて（笑）」`,
        ch: [{ t: "🔥 受けて立つ！", fx: {}, after: () => startQuiz({
          mode: "lesson", genre: "kufuu", lv: 2, total: 1,
          fixed: [{ ...qq, small: true, time: 25, genre: "kufuu" }],
          title: "⚡ とっさの暗算",
          onEnd: r => {
            G.totalQ += r.total; G.totalOK += r.correct;
            const okQ = r.correct === 1;
            if (okQ) G.fans += 600;
            save();
            $("ovResult").classList.remove("on");
            showEvent({
              c: okQ ? "riku" : "tsukasa",
              t: okQ
                ? "ショリ「即答！！ 会場どよめいたよ（笑）\nこういう『持ちネタ』があるって強いなあ。\n……番組で使えるよ、それ」"
                : "フマ「……おい、計算キャラが外すな（笑）\nでもな、外したあとの顔が良かった。\nミスって笑いに変えるのも、バラエティの実力だ」",
              ch: [{ t: "▶", fx: okQ ? { fans: 0 } : { st: { tk: 2 } }, after: () => askCard(2, () => {
                addStat("tk", 6);
                showEvent({
                  c: "tsukasa",
                  t: `フマ「……以上、ぶっちゃけ質問箱でした。\n\n${G.name}。おまえ、しゃべれるようになってきたな。\n歌もダンスも大事だ。でもな、\n『この子と話したい』って思わせたやつが、最後に残る。\n\n……今日のおまえは、残る側の顔してたぞ」`,
                  ch: [{ t: "「ありがとうございました！」", fx: { st: { tk: 3 }, fans: 400 }, after: done }]
                });
              }) }]
            });
          }
        }) }]
      });
    })) }]
  });
}

const SUSHI_QS = [
  { q: "タクトの大好物・ほたて。1皿に 2かんのって、7皿食べると ぜんぶで何かん？", a: { t: "num", v: 14, unit: "かん" }, tag: "すし算" },
  { q: "1皿 115円のお寿司を 8皿。代金は 何円？", a: { t: "num", v: 920, unit: "円" }, tag: "すし算", note: "くふう：115×8＝(100＋15)×8" },
  { q: "タクトときみで 合わせて21皿。タクトはきみの 2倍食べた。きみは 何皿？", a: { t: "num", v: 7, unit: "皿" }, tag: "すし算（倍数算）", note: "きみ＋きみ×2＝21" },
  { q: "5皿ごとに ガチャが1回まわせる。23皿では 何回まわせる？", a: { t: "num", v: 4, unit: "回" }, tag: "すし算（周期）", note: "23÷5 の商" },
  { q: "サーモン120円を 6皿、たまご90円を 4皿。合計は 何円？", a: { t: "num", v: 1080, unit: "円" }, tag: "すし算", note: "720＋360" },
];
function startSushi(done) {
  showEvent({
    c: "takuto",
    scene: "img/scene_sushi.jpg",
    t: "「{name}！ 今日は特訓なし！\n……じゃーん。くら寿司の割引券、もらっちゃった。\n一緒に行こうぜ。\n\n知ってるか？ おれ、貝がこの世でいちばん好きなんだ。\nほたて、赤貝、つぶ貝……今日は貝祭りだ。\n\nたくさん食べるやつは、伸びる。これ、お兄さんの持論な」",
    ch: [{ t: "🍣 行く！！", fx: {}, after: () => startQuiz({
      mode: "lesson", genre: "kufuu", lv: 3, total: 5,
      fixed: SUSHI_QS.map(q => ({ ...q, small: true, time: 60, genre: "kufuu" })),
      title: "🍣 回転ずしチャレンジ",
      onEnd: r => {
        G.totalQ += r.total; G.totalOK += r.correct;
        const heal = 40;
        G.stam = Math.min(G.maxStam, G.stam + heal);
        const gains = [];
        STATS.forEach(st => { const d = addStat(st.k, 3); if (d) gains.push([st.n, d]); });
        G.aff.takuto = clamp((G.aff.takuto || 0) + 15, 0, 100);
        const perfect = r.correct === 5;
        if (perfect) G.fans += 500;
        confetti(perfect ? 50 : 24); sfx.clear(); save();
        $("resPanel").innerHTML = `
          <div class="resHead">
            <div class="lbl">🍣 回転ずしチャレンジ</div>
            <div class="resScore" style="font-size:34px">${r.correct} / 5 皿</div>
            <div class="resRank" style="background:${perfect ? "#ffcf5c" : "#4ad6b8"};color:#0a0a11">${perfect ? "🎉 ガチャ大当たり！" : "ごちそうさま！"}</div>
          </div>
          <div class="gains">
            <div class="gain"><span>体力（おいしいごはん）</span><b>+${heal}</b></div>
            ${gains.map(g => `<div class="gain"><span>${g[0]}</span><b>+${g[1]}</b></div>`).join("")}
            <div class="gain"><span>タクトの好感度</span><b>+15</b></div>
            ${perfect ? `<div class="gain"><span>📈 注目度（ガチャ大当たり）</span><b>+500</b></div>` : ""}
          </div>
          <button class="btn" id="resOk">ごちそうさま</button>`;
        $("ovResult").classList.add("on");
        $("resOk").onclick = () => {
          sfx.tap(); $("ovResult").classList.remove("on");
          showEvent({
            c: "takuto",
            scene: "img/scene_sushi.jpg",
            t: perfect
              ? "「全問正解かよ！ 参ったな……\nガチャの景品、おまえにやるよ。\n\nお祝いに、おれの最後のほたて……はやれない。貝だけは譲れない。\n\nこういう時間も、ぜんぶ力になるんだ。\nまた来ような。次はおれのおごり」"
              : "「よく食べたな〜。……いい顔になった。\n\n机の前だけが練習じゃない。\nこういう時間も、ぜんぶ力になるんだよ。\n……また来よう」",
            ch: [{ t: "「ごちそうさまでした！」", fx: { cond: 1 }, after: done }]
          });
        };
      }
    }) }]
  });
}

